/************************************************
 * Web App Entry Point
 ************************************************/
function doGet(e) {


  // No parameters -> Show Manual UI

if (!e || !e.parameter.action) {

  return ContentService
    .createTextOutput(
      JSON.stringify({
        success: false,
        message: "Missing action parameter."
      })
    )
    .setMimeType(ContentService.MimeType.JSON);

}

  switch (e.parameter.action) {

    case "lookup":

      return ContentService
        .createTextOutput(
          JSON.stringify(
            lookupToken(e.parameter.token)
          )
        )
        .setMimeType(ContentService.MimeType.JSON);

    case "search":

  return ContentService
    .createTextOutput(
      JSON.stringify(
        searchParticipant(
          e.parameter.search
        )
      )
    )
    .setMimeType(ContentService.MimeType.JSON);

    case "checkin":

      return ContentService
        .createTextOutput(
          JSON.stringify(
            confirmCheckIn(
              e.parameter.token,
              e.parameter.counter || "Counter 1"
            )
          )
        )
        .setMimeType(ContentService.MimeType.JSON);



    case "statistics":

      return ContentService
        .createTextOutput(
        JSON.stringify(
        getCheckInStatistics()
      )
    )
    .setMimeType(ContentService.MimeType.JSON);

    case "version":

     return ContentService
    .createTextOutput(
      JSON.stringify(diagnostics())
    )
    .setMimeType(ContentService.MimeType.JSON);

    default:

      return ContentService
        .createTextOutput(
          JSON.stringify({
            success:false,
            message:"Invalid Action"
          })
        )
        .setMimeType(ContentService.MimeType.JSON);

  }

}

