}
/**
 * Reset all check-ins
 */
function resetCheckIn() {

  const sheet = SpreadsheetApp.openById(CONFIG.SPREADSHEET_ID)
    .getSheetByName(CONFIG.SHEET_NAME);

  const lastRow = sheet.getLastRow();

  if (lastRow < 2) return;

  // Reset checkboxes (Column H)
  sheet.getRange(2, COL.CHECKEDIN, lastRow - 1, 1)
       .setValue(false);

  // Clear Check-in Time and Checked By
  sheet.getRange(2, COL.CHECKINTIME, lastRow - 1, 2)
       .clearContent();

  SpreadsheetApp.getUi().alert("All check-ins have been reset.");

}




function getCheckInStatistics() {

  const start = Date.now();

  const sheet = SpreadsheetApp
    .openById(CONFIG.SPREADSHEET_ID)
    .getSheetByName(CONFIG.SHEET_NAME);

  const lastRow = sheet.getLastRow();

  if (lastRow < 2) {

    return withServerTime({

      success: true,

      totalEntries: 0,
      checkedInEntries: 0,

      totalParticipants: 0,
      checkedInParticipants: 0,

      entryCheckInPercent: 0,
      participantCheckInPercent: 0

    }, start);
  }

  const data = sheet
    .getRange(
      2,
      1,
      lastRow - 1,
      COL.CHECKEDBY
    )
    .getValues();

  let totalEntries = 0;
  let checkedInEntries = 0;

  let totalParticipants = 0;
  let checkedInParticipants = 0;

  data.forEach(function(row) {

    // Registration ID must exist
    // to consider this a valid entry.
    const regid =
      String(row[COL.REGID - 1]).trim();

    if (regid === "") {
      return;
    }

    totalEntries++;

    const bands =
      Number(row[COL.BANDS - 1]) || 0;

    totalParticipants += bands;

    const checked =
      row[COL.CHECKEDIN - 1] === true;

    if (checked) {

      checkedInEntries++;

      checkedInParticipants += bands;

    }

  });

  const entryCheckInPercent =
    totalEntries > 0
      ? (checkedInEntries / totalEntries) * 100
      : 0;

  const participantCheckInPercent =
    totalParticipants > 0
      ? (checkedInParticipants / totalParticipants) * 100
      : 0;

  return withServerTime({

    success: true,

    totalEntries: totalEntries,

    checkedInEntries: checkedInEntries,

    totalParticipants: totalParticipants,

    checkedInParticipants: checkedInParticipants,

    entryCheckInPercent:
      entryCheckInPercent,

    participantCheckInPercent:
      participantCheckInPercent

  }, start);

}

/************************************************
 * Lookup.gs
 * Participant Search
 ************************************************/
function searchParticipant(searchText) {

  const start = Date.now();

  searchText = String(searchText || "").trim().toLowerCase();

  if (searchText === "") {
    return withServerTime({
      found: false,
      message: "Please enter a search value."
    }, start);
  }

  const sheet = SpreadsheetApp
    .openById(CONFIG.SPREADSHEET_ID)
    .getSheetByName(CONFIG.SHEET_NAME);

  const lastRow = sheet.getLastRow();

  if (lastRow < 2) {
    return withServerTime({
      found: false,
      message: "No registrations found."
    }, start);
  }

  const data = sheet.getRange(
    2,
    1,
    lastRow - 1,
    COL.CHECKEDBY
  ).getValues();

  // =====================================================
  // PASS 1
  // Exact search
  // Token / Registration / Email
  // =====================================================

  for (let i = 0; i < data.length; i++) {

    const token =
      String(data[i][COL.TOKEN - 1]).trim().toLowerCase();

    const regid =
      String(data[i][COL.REGID - 1]).trim().toLowerCase();

    const email =
      String(data[i][COL.EMAIL - 1]).trim().toLowerCase();

    if (
      token === searchText ||
      regid === searchText ||
      email === searchText
    ) {

      return withServerTime({

        found: true,

        row: i + 2,

        regid: data[i][COL.REGID - 1],

        name: data[i][COL.NAME - 1],

        email: data[i][COL.EMAIL - 1],

        token: data[i][COL.TOKEN - 1],

        bands: Number(data[i][COL.BANDS - 1]),

        adults: Number(data[i][COL.ADULTS - 1]),

        children: Number(data[i][COL.CHILDREN - 1]),

        checked: data[i][COL.CHECKEDIN - 1] === true,

        checkinTime: data[i][COL.CHECKINTIME - 1],

        checkedBy: data[i][COL.CHECKEDBY - 1],

        serverTime: Date.now()-start

      }, start);

    }

  }

  // =====================================================
  // PASS 2
  // Name search
  // =====================================================

  const matches = [];

  for (let i = 0; i < data.length; i++) {

    const name =
      String(data[i][COL.NAME - 1]).trim().toLowerCase();

       // Logger.log("Search = [" + searchText + "]");
    // Logger.log("Name   = [" + name + "]");

    if (name.indexOf(searchText) >= 0) {

      matches.push({

        row: i + 2,

        regid: data[i][COL.REGID - 1],

        name: data[i][COL.NAME - 1],

        email: data[i][COL.EMAIL - 1],

        token: data[i][COL.TOKEN - 1],

        bands: Number(data[i][COL.BANDS - 1]),

        adults: Number(data[i][COL.ADULTS - 1]),

        children: Number(data[i][COL.CHILDREN - 1]),

        checked: data[i][COL.CHECKEDIN - 1] === true,

        checkinTime: data[i][COL.CHECKINTIME - 1],

        checkedBy: data[i][COL.CHECKEDBY - 1]

      });

    }

  }

// Logger.log("Search = " + searchText);
// Logger.log("Matches = " + matches.length);

// matches.forEach(function(m){
 // Logger.log(m.name);
//});
  // =====================================================
  // Result
  // =====================================================

  if (matches.length === 1) {

    return withServerTime({

      found: true,

      ...matches[0]

    }, start);

  }

  if (matches.length > 1) {

    return withServerTime({

      found: true,

      multiple: true,

      results: matches

    }, start);

  }

  return withServerTime( {

    found: false,

    message: "No participant found."

  }, start);

}

/**
 * Find participant by QR Token
 */
function lookupToken(token) {

const start = Date.now();

  token = String(token).trim();

  if (token === "") {
    return {
      found: false,
      message: "No token supplied."
    };
  }

  const sheet = SpreadsheetApp.openById(CONFIG.SPREADSHEET_ID)
    .getSheetByName(CONFIG.SHEET_NAME);

    Logger.log("Open sheet: " + (Date.now() - start) + " ms");

  const lastRow = sheet.getLastRow();

  if (lastRow < 2) {
    return {
      found: false,
      message: "No registrations found."
    };
  }

  const data = sheet.getRange(2, 1, lastRow - 1, COL.CHECKEDBY).getValues();

  Logger.log("Read sheet: " + (Date.now() - start) + " ms");

  for (let i = 0; i < data.length; i++) {

    if (String(data[i][COL.TOKEN - 1]).trim() === token) {

Logger.log("lookupToken total: " + (Date.now() - start) + " ms");
      return withServerTime({

        found: true,

        row: i + 2,

        regid: data[i][COL.REGID - 1],

        name: data[i][COL.NAME - 1],

        email: data[i][COL.EMAIL - 1],

        token: data[i][COL.TOKEN - 1],

        bands: Number(data[i][COL.BANDS - 1]),

        adults: Number(data[i][COL.ADULTS - 1]),

        children: Number(data[i][COL.CHILDREN - 1]),

        checked: data[i][COL.CHECKEDIN - 1] === true,

        checkinTime: data[i][COL.CHECKINTIME - 1],

        checkedBy: data[i][COL.CHECKEDBY - 1]

      }, start);

    }

  }

Logger.log("lookupToken total: " + (Date.now() - start) + " ms");
  return withServerTime({



    found: false,

    message: "Participant not found."

  }, start);

}

function withServerTime(result, start) {
  result.serverTime = Date.now() - start;
  return result;
}

function lookupTokenInData(data, token) {

  token = String(token || "").trim().toLowerCase();

  for (let i = 0; i < data.length; i++) {

    if (
      String(data[i][COL.TOKEN - 1]).trim().toLowerCase() === token
    ) {

      return {

        found: true,

        row: i + 2,

        regid: data[i][COL.REGID - 1],

        name: data[i][COL.NAME - 1],

        email: data[i][COL.EMAIL - 1],

        token: data[i][COL.TOKEN - 1],

        bands: Number(data[i][COL.BANDS - 1]),

        adults: Number(data[i][COL.ADULTS - 1]),

        children: Number(data[i][COL.CHILDREN - 1]),

        checked: data[i][COL.CHECKEDIN - 1] === true,

        checkinTime: data[i][COL.CHECKINTIME - 1],

        checkedBy: data[i][COL.CHECKEDBY - 1]

      };

    }

  }

  return {

    found: false,

    message: "Participant not found."

  };

}


