/************************************************
 * CheckIn.gs
 * Production Version
 ************************************************/

/**
 * Confirm participant check-in
 *
 * @param {string} token   QR Token
 * @param {string} counter Counter Name
 * @returns {Object}
 */
function confirmCheckIn(token, counter) {

const start = Date.now();
  const lock = LockService.getScriptLock();
    lock.waitLock(10000);
  Logger.log("Lock obtained: " + (Date.now() - start) + " ms");

  try {


const sheet = SpreadsheetApp
  .openById(CONFIG.SPREADSHEET_ID)
  .getSheetByName(CONFIG.SHEET_NAME);

const lastRow = sheet.getLastRow();

const data = sheet
  .getRange(2, 1, lastRow - 1, COL.CHECKEDBY)
  .getValues();

const person = lookupTokenInData(data, token);
Logger.log("Lookup finished: " + (Date.now() - start) + " ms");

if (!person.found) {

  return withServerTime({
    success: false,
    code: "NOT_FOUND",
    message: "Participant not found."
  }, start);

}

    // Already checked in
    if (person.checked === true) {

      return withServerTime({
        success: false,
        code: "ALREADY_CHECKED_IN",
        message: "Participant already checked in.",
        name: person.name,
        regid: person.regid,
        checkinTime: person.checkinTime,
        checkedBy: person.checkedBy
      }, start);

    }



    const row = person.row;

sheet.getRange(row, COL.CHECKEDIN, 1, 3)
     .setValues([
         [true, new Date(), counter]
     ]);

     Logger.log("Write finished: " + (Date.now() - start) + " ms");

    return withServerTime({

      success: true,

      code: "SUCCESS",

      regid: person.regid,

      name: person.name,

      bands: person.bands,

      adults: person.adults,

      children: person.children,

      counter: counter

    }, start);

  }
  finally {

    lock.releaseLock();

  }

}

