/************************************************
 * QR.gs
 * QR Code Generation & Email Helpers
 ************************************************/

/**
 * Generate QR image URL from token
 */
function getQrImageUrl(token) {

  token = encodeURIComponent(token);

  return "https://chart.googleapis.com/chart" +
         "?cht=qr" +
         "&chs=300x300" +
         "&chl=" + token;

}


/**
 * Generate QR Formula inside sheet
 * (Optional)
 */
function generateQrFormula() {

  const sheet = SpreadsheetApp.openById(CONFIG.SPREADSHEET_ID)
      .getSheetByName(CONFIG.SHEET_NAME);

  const lastRow = sheet.getLastRow();

  let qrColumn = sheet.getLastColumn() + 1;

  sheet.getRange(1, qrColumn).setValue("QR");

  for (let r = 2; r <= lastRow; r++) {

    let token = sheet.getRange(r, COL.TOKEN).getValue();

    sheet.getRange(r, qrColumn).setFormula(

      '=IMAGE("' + getQrImageUrl(token) + '")'

    );

  }

}


/**
 * Get QR Blob
 */
function getQrBlob(token) {

  const url = getQrImageUrl(token);

  return UrlFetchApp
      .fetch(url)
      .getBlob()
      .setName(token + ".png");

}


