/************************************************
 * Email.gs
 ************************************************/

/**
 * Send QR email to one participant
 */
function sendEmailToRow(row) {

  const sheet = SpreadsheetApp.openById(CONFIG.SPREADSHEET_ID)
    .getSheetByName(CONFIG.SHEET_NAME);

  const name = sheet.getRange(row, COL.NAME).getValue();
  const email = sheet.getRange(row, COL.EMAIL).getValue();
  const token = sheet.getRange(row, COL.TOKEN).getValue();

  if (email == "") return;

  // QR Image URL
  const qrUrl =
    "https://api.qrserver.com/v1/create-qr-code/" +
    "?size=300x300&data=" +
    encodeURIComponent(token);

  // Download QR image
  const qrBlob = UrlFetchApp
    .fetch(qrUrl)
    .getBlob()
    .setName("MonthiFestQR.png");

  const subject = CONFIG.EVENT_NAME + " - Your QR Code";

  const html =
  `
  <div style="font-family:Arial">

    <h2>${CONFIG.EVENT_NAME}</h2>

    <p>Dear <b>${name}</b>,</p>

    <p>
      Thank you for registering.
    </p>

    <p>
      Please keep the attached QR Code ready at the registration desk.
    </p>

    <p>
      Registration Token:<br>
      <b>${token}</b>
    </p>

    <p>
      We look forward to welcoming you.
    </p>

    <br>

    <b>${CONFIG.ORGANISATION}</b>

  </div>
  `;

  GmailApp.sendEmail(

    email,

    subject,

    "Please view HTML version.",

    {

      htmlBody: html,

      attachments: [qrBlob]

    }

  );



}

  /**
 * Send QR emails
 */
function sendAllEmails() {

  const sheet = SpreadsheetApp.openById(CONFIG.SPREADSHEET_ID)
      .getSheetByName(CONFIG.SHEET_NAME);

  const lastRow = sheet.getLastRow();

  for(let r=2;r<=lastRow;r++){

      sendEmailToRow(r);

      Utilities.sleep(1000);

  }

}


